node -e "
const ExcelJS = require('exceljs');

async function createFile() {
  const workbook = new ExcelJS.Workbook();
  const sheet = workbook.addWorksheet('Sheet1');

  sheet.columns = [
    { header: 'Name', key: 'name', width: 15 },
    { header: 'Email', key: 'email', width: 30 }
  ];

  sheet.addRow({ name: 'alice', email: 'alice@example.com' });

  // Bold the header row
  sheet.getRow(1).font = { bold: true };

  await workbook.xlsx.writeFile('/workspace/alice_data.xlsx');
  console.log('File created successfully!');
}

createFile();
"

node -e "
const ExcelJS = require('exceljs');

async function readFile() {
  const workbook = new ExcelJS.Workbook();
  await workbook.xlsx.readFile('/workspace/alice_data.xlsx');
  const sheet = workbook.getWorksheet('Sheet1');
  sheet.eachRow((row, rowNum) => {
    console.log('Row ' + rowNum + ': ' + row.values.slice(1).join(' | '));
  });
}

readFile();
"
